args.new_string:
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('http://localhost:3000/api/analytics').then(r => r.json()),
      fetch('http://localhost:3000/api/notifications').then(r => r.json()),
      fetch('http://localhost:3000/api/settings').then(r => r.json()),
    ]);

    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { pageViews: 0, uniqueVisitors: 0, bounceRate: 0, avgSessionDuration: '0m 0s' },
      notifications: { notifications: [] },
      settings: { theme: 'light', language: 'en', emailNotifications: true },
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page Views: {analytics.pageViews}</p>
        <p>Unique Visitors: {analytics.uniqueVisitors}</p>
        <p>Bounce Rate: {analytics.bounceRate}%</p>
        <p>Avg Session Duration: {analytics.avgSessionDuration}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        <ul>
          {notifications.notifications.map((n: { id: number; message: string; read: boolean }) => (
            <li key={n.id}>
              {n.message} {n.read ? '(read)' : '(unread)'}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Language: {settings.language}</p>
        <p>Email Notifications: {settings.emailNotifications ? 'Enabled' : 'Disabled'}</p>
      </section>
    </div>
  );
}

